#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<long long> a(3*n+1);
        for(int i=1 ;i<=3*n;i++){
            cin>>a[i];
        }
        sort(a.begin()+1,a.end(),greater<long long>());
        vector<long long> pref(3*n+1,0);
        for(int i=1 ;i<=3*n;i++){
            pref[i] = pref[i-1] + a[i];
            
        }
        long long answer = 0;
        for(int x =0 ;x<=n ; x++){
            int maxY = n-x;
            int lo = 0,hi =maxY;
            while(lo<hi){
                int mid = (lo+hi+1)/2;
                int left = x+2*(mid -1);
                int right = 3*n-2*x-(mid-1);
                long long yxz = a[left+1]+a[left+2]-3LL*a[right];
                if(yxz >= 0)
                   lo = mid;
                else
                   hi = mid -1;
        }
        int y = lo;
        int p = x+2*y;
        int q = 3*n-2*x-y;
        long long current = 2LL * pref[x] + pref[p]+3LL*pref[q];
        answer = max(answer,current);
    }
    cout<<answer<<'\n';
    
}
return 0;
}
